// Node tests for the pure results module (src/results.ts — docs/08 R25): the
// simulation log, the run verdict, the attribution of a report to an element of
// the verification view, imc's coverage summary, the folded snapshot, the
// projection onto one level, the header sentence and the report.
//
// The fixtures under scripts/fixtures/results/ are REAL: the yapp_buffer
// tutorial bench generated by quick-uvm 1.1.0 and run with `make regress` on
// Xcelium 25.09 (paths sanitised) — `fatal/` with the generated predictor stub
// still in place, `errors/` with a deliberately wrong prediction.
//   npm run test:results
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import esbuild from "esbuild";

const outDir = mkdtempSync(join(tmpdir(), "quickuvm-results-"));
const outFile = join(outDir, "results.mjs");
await esbuild.build({
  entryPoints: ["src/results.ts"],
  outfile: outFile,
  bundle: true,
  format: "esm",
  platform: "node",
  logLevel: "silent",
});
const R = await import(pathToFileURL(outFile));

let passed = 0;
function test(name, fn) {
  fn();
  passed += 1;
  console.log(`  ok ${name}`);
}
const fx = (...p) => readFileSync(join("scripts/fixtures/results", ...p), "utf8");
const run = (set, dir) =>
  R.runResult(dir, {
    status: fx(set, "runs", dir, "status"),
    test: fx(set, "runs", dir, "test.txt"),
    seed: fx(set, "runs", dir, "seed.txt"),
    log: fx(set, "runs", dir, "sim.log"),
  });
const NAMES = { dut: "yapp_buffer", agents: ["cmd", "rsp"], scoreboards: ["pkt_sb"], subenvs: [] };
const OK_LOG =
  "UVM_INFO @ 0: reporter [RNTST] Running test t...\n** Report counts by severity\nUVM_INFO :    3\nUVM_WARNING :    2\nUVM_ERROR :    0\nUVM_FATAL :    0\n** Report counts by id\n[RNTST]     1\n\nSimulation complete via $finish(1) at time 65 NS + 3\n";

// ------------------------------------------------------------------ the log
test("log (real, fatal): one UVM_FATAL from the predictor, the server's counts, $finish, the scope", () => {
  const log = R.parseSimLog(fx("fatal", "runs", "yapp_buffer_test.1", "sim.log"));
  assert.deepEqual(log.counts, { info: 3, warning: 0, error: 0, fatal: 1 });
  assert.equal(log.finished, true);
  assert.equal(log.scope, "yapp_buffer", "`-covscope <dut>`: whose results these are");
  assert.equal(log.reports.length, 1, "the INFOs are counted, not kept");
  const r = log.reports[0];
  assert.equal(r.severity, "fatal");
  assert.equal(r.file, "../tb/yapp_buffer_reference_model.svh");
  assert.equal(r.line, 43);
  assert.equal(r.time, 65);
  assert.equal(r.path, "uvm_test_top.e.pkt_sb.prd");
  assert.equal(r.id, "UNFILLED_PREDICTOR");
  assert.equal(r.count, 1);
  assert.ok(r.message.startsWith("the `prediction_logic` seam is still the generated stub"));
});

test("log (real, errors): 103 reports fold into 4 kinds while parsing; the catcher's zeros are not read", () => {
  const text = fx("errors", "runs", "yapp_buffer_test.1", "sim.log");
  const log = R.parseSimLog(text);
  assert.deepEqual(log.counts, { info: 4, warning: 1, error: 102, fatal: 0 });
  // one entry per KIND (severity + reporter + id + source line), with a count
  assert.deepEqual(
    log.reports.map((r) => [r.severity, r.id, r.line, r.count]),
    [["error", "SB_NOEXP", 84, 31], ["error", "ERROR", 135, 70], ["warning", "SB_LEFTOVER", 101, 1], ["error", "FAILED", 106, 1]]
  );
  assert.equal(log.reports.filter((r) => r.severity === "error").reduce((n, r) => n + r.count, 0), 102, "every error line is counted");
  assert.equal(log.reports[0].time, 65, "the time and the text of the FIRST of a kind");
  assert.deepEqual([...new Set(log.reports.map((r) => r.path))], ["uvm_test_top.e.pkt_sb.cmp"]);
  assert.equal(log.dropped, 0);
  // the report CATCHER prints "Number of caught UVM_ERROR reports : 0" on this
  // failing run — a parser that read it would call the run clean
  assert.ok(text.includes("Number of caught UVM_ERROR reports   :    0"));
  assert.equal(R.verdictOf(log), "FAIL");
});

test("fold key: severity, reporter, id, file AND line — any one differing is another kind", () => {
  const l = (sev, path, id, line) => `${sev} ../tb/x.svh(${line}) @ 5: ${path} [${id}] m`;
  const log = R.parseSimLog(
    [
      l("UVM_ERROR", "uvm_test_top.e.a", "X", 1),
      l("UVM_ERROR", "uvm_test_top.e.a", "X", 1),
      l("UVM_ERROR", "uvm_test_top.e.a", "X", 2), // another line
      l("UVM_WARNING", "uvm_test_top.e.a", "X", 1), // another severity
      l("UVM_ERROR", "uvm_test_top.e.b", "X", 1), // another reporter
      l("UVM_ERROR", "uvm_test_top.e.a", "Y", 1), // another id
    ].join("\n")
  );
  assert.deepEqual(log.reports.map((r) => r.count), [2, 1, 1, 1, 1]);
});

test("verdict of a log: $finish AND a COMPLETE severity block with no error and no fatal", () => {
  assert.equal(R.verdictOf(R.parseSimLog(OK_LOG)), "PASS", "warnings do not fail a run");
  assert.equal(R.verdictOf(R.parseSimLog(OK_LOG.replace("UVM_ERROR :    0", "UVM_ERROR :    1"))), "FAIL");
  assert.equal(R.verdictOf(R.parseSimLog(OK_LOG.replace(/Simulation complete.*\n/, ""))), "FAIL", "never reached $finish");
  assert.equal(R.verdictOf(R.parseSimLog("xmsim: *F,NOSNAP: snapshot not found\n")), "FAIL", "a crash has no summary");
  assert.equal(R.verdictOf(R.parseSimLog("")), "FAIL");
  // "[ERROR]    70" in the by-id block is an ID count, not the severity block
  assert.equal(R.parseSimLog(OK_LOG.replace("[RNTST]     1", "[ERROR]    70")).counts.error, 0);
  // review: a block CUT after its first line is not a summary — pre-zeroed
  // counts read as "no errors" and the run passed
  const cut = "** Report counts by severity\nUVM_INFO :    3\nSimulation complete via $finish(1) at time 5\n";
  assert.equal(R.parseSimLog(cut).counts, null);
  assert.equal(R.verdictOf(R.parseSimLog(cut)), "FAIL");
  // review: a REPORT whose text mentions $finish is a report, not the end of the run
  const quoted = R.parseSimLog("UVM_ERROR ../tb/x.svh(3) @ 5: uvm_test_top.e [Q] expected: Simulation complete via $finish\n");
  assert.equal(quoted.finished, false);
  assert.equal(quoted.reports.length, 1);
  // a restarted run: the LAST summary counts
  const twice = R.parseSimLog(OK_LOG.replace("UVM_ERROR :    0", "UVM_ERROR :    4") + OK_LOG);
  assert.equal(twice.counts.error, 0);
});

test("report lines: no file, a time unit, CRLF, brackets in the message and in the id, a Questa prefix", () => {
  const log = R.parseSimLog(
    [
      "UVM_ERROR @ 120: reporter [TIMEOUT] no file here",
      "UVM_WARNING /a b/c.svh(7) @ 15 ns: uvm_test_top.e.cmd_agnt.mon [X/Y] got [3] items\r",
      "UVM_ERROR : this is not a report",
      "  UVM_ERROR ../tb/x.svh(1) @ 5: uvm_test_top [INDENTED] not at the line start",
      "UVM_INFO ../tb/x.svh(1) @ 5: uvm_test_top [I] skipped",
      "UVM_ERROR ../tb/x.svh(9) @ 5: uvm_test_top.e [a[0]] an id with brackets",
      "# UVM_ERROR ../tb/x.svh(2) @ 5: uvm_test_top.e [Q] a transcript line",
    ].join("\n")
  );
  assert.deepEqual(log.reports, [
    { severity: "error", file: null, line: null, time: 120, path: "reporter", id: "TIMEOUT", message: "no file here", count: 1 },
    { severity: "warning", file: "/a b/c.svh", line: 7, time: 15, path: "uvm_test_top.e.cmd_agnt.mon", id: "X/Y", message: "got [3] items", count: 1 },
    { severity: "error", file: "../tb/x.svh", line: 9, time: 5, path: "uvm_test_top.e", id: "a[0]", message: "an id with brackets", count: 1 },
    { severity: "error", file: "../tb/x.svh", line: 2, time: 5, path: "uvm_test_top.e", id: "Q", message: "a transcript line", count: 1 },
  ]);
  assert.equal(log.scope, null, "no coverage scope: the owner cannot be told");
});

// ------------------------------------------------------------------ the run
test("run: the STATUS file is the verdict — without one the run has none (in flight), whatever its log says", () => {
  const r = run("errors", "yapp_buffer_test.1");
  assert.deepEqual([r.test, r.seed, r.status, r.scope], ["yapp_buffer_test", "1", "FAIL", "yapp_buffer"]);
  assert.deepEqual(r.counts, { info: 4, warning: 1, error: 102, fatal: 0 });
  assert.equal(r.missed, 0, "every counted report was read");
  // test and seed fall back to the directory name
  const bare = R.runResult("my.test.7", {});
  assert.deepEqual([bare.test, bare.seed, bare.status], ["my.test", "7", "UNKNOWN"]);
  // review: the Makefile writes `status` AFTER the simulator exits; a run
  // without it is running (or was killed). Its half-written log is not a verdict
  const log = fx("fatal", "runs", "yapp_buffer_test.1", "sim.log");
  assert.equal(R.runResult("t.1", { log }).status, "UNKNOWN");
  assert.equal(R.runResult("t.1", { log: log.slice(0, log.length / 2) }).status, "UNKNOWN");
  assert.equal(R.runResult("t.1", { log: OK_LOG }).status, "UNKNOWN", "not even a clean log");
  assert.equal(R.runResult("t.1", { log, status: "pass\r\n" }).status, "PASS", "the Makefile's file is authoritative");
  assert.equal(R.runResult("t.1", { status: "FAILED" }).status, "UNKNOWN");
  assert.equal(R.runResult("t.1", { status: "" }).status, "UNKNOWN");
  // a log cut before the summary: the counts are what was parsed
  const cut = R.runResult("t.1", { log: "UVM_ERROR @ 1: uvm_test_top.e.pkt_sb [A] x\n" });
  assert.deepEqual(cut.counts, { info: 0, warning: 0, error: 1, fatal: 0 });
  // the simulator counted more than could be read: SAID, not silently short
  const odd = OK_LOG.replace("UVM_ERROR :    0", "UVM_ERROR :    5");
  assert.equal(R.runResult("t.1", { log: odd, status: "FAIL" }).missed, 7, "2 warnings + 5 errors on no line this parser knows");
});

// -------------------------------------------------------------- attribution
test("attribution: a path names its element by the generator's instance names", () => {
  const at = (p) => R.elementOfPath(p, NAMES);
  const ex = (id, unit = null) => ({ id, unit, exact: true });
  assert.deepEqual(at("uvm_test_top.e.pkt_sb.cmp"), ex("sb:pkt_sb"));
  assert.deepEqual(at("uvm_test_top.e.pkt_sb"), ex("sb:pkt_sb"));
  assert.deepEqual(at("uvm_test_top.e.cmd_agnt.mon"), ex("agent:cmd", "u.monitor"));
  assert.deepEqual(at("uvm_test_top.e.rsp_agnt.drv"), ex("agent:rsp", "u.driver"));
  assert.deepEqual(at("uvm_test_top.e.cmd_agnt"), ex("agent:cmd"));
  assert.deepEqual(at("uvm_test_top.e.cmd_cov_h"), ex("cov:cmd"));
  assert.deepEqual(at("uvm_test_top.e.vsqr"), ex("vsqr"));
  assert.deepEqual(at("uvm_test_top.e"), ex("env"));
  assert.deepEqual(at("uvm_test_top"), ex("env"));
  assert.deepEqual(at("uvm_test_top.e.something_else.x"), { id: "env", unit: null, exact: false },
    "under the env, in an instance nobody knows: the caller tries the source file first");
  assert.equal(at("reporter"), null, "not under the test: the caller decides");
  // the env's instance name is a position, not a name
  assert.deepEqual(R.elementOfPath("uvm_test_top.my_env.pkt_sb", NAMES), ex("sb:pkt_sb"));
  // an agent the config does not have is not invented
  assert.equal(at("uvm_test_top.e.ghost_agnt.mon").exact, false);
  // a composed block: anything inside it is the block's
  assert.deepEqual(
    R.elementOfPath("uvm_test_top.e.ch0.chan_a_agnt.mon", { agents: [], scoreboards: [], subenvs: ["ch0"] }),
    ex("sub:ch0")
  );
  // an agent NAMED like another's suffix does not swallow it
  const tricky = { agents: ["a", "a_cov_h"], scoreboards: [], subenvs: [] };
  assert.deepEqual(R.elementOfPath("uvm_test_top.e.a_cov_h_agnt", tricky), ex("agent:a_cov_h"));
  assert.deepEqual(R.elementOfPath("uvm_test_top.e.a_cov_h", tricky), ex("cov:a"));
});

test("attribution (review): the names quick-uvm really generates — sequences, implicit mode, replicas, probes", () => {
  const at = (p, n) => R.elementOfPath(p, n);
  const ex = (id, unit = null) => ({ id, unit, exact: true });
  // a sequence reports through its sequencer as `sqr@@<sequence>`
  assert.deepEqual(at("uvm_test_top.e.cmd_agnt.sqr@@cmd_seq", NAMES), ex("agent:cmd", "u.sequencer"));
  assert.deepEqual(at("uvm_test_top.e.vsqr@@my_vseq", NAMES), ex("vsqr"));
  // implicit mode (no `analysis:`): the scoreboard is `sbd`, the collector `cov`
  const implicit = { agents: ["cmd", "rsp"], scoreboards: ["sbd"], subenvs: [], implicitCoverage: "cmd" };
  assert.deepEqual(at("uvm_test_top.e.sbd.cmp", implicit), ex("sb:sbd"));
  assert.deepEqual(at("uvm_test_top.e.cov", implicit), ex("cov:cmd"));
  assert.equal(at("uvm_test_top.e.cov", NAMES).exact, false, "a declared bench has no instance `cov`");
  // a sole agent replicated / instantiated: `<handle>_agnt`, `<handle>_sb`
  const sole = { agents: ["cmd"], scoreboards: ["pkt_sb"], subenvs: [], soleAgent: "cmd" };
  assert.deepEqual(at("uvm_test_top.e.cmd_0_agnt.mon", sole), ex("agent:cmd", "u.monitor"));
  assert.deepEqual(at("uvm_test_top.e.lo_agnt.drv", sole), ex("agent:cmd", "u.driver"));
  assert.deepEqual(at("uvm_test_top.e.cmd_1_sb.cmp", sole), ex("sb:pkt_sb"));
  assert.equal(at("uvm_test_top.e.cmd_0_agnt.mon", NAMES).exact, false, "not on a bench with several agents");
  // the probe monitor
  assert.deepEqual(at("uvm_test_top.e.probe_mon", { ...NAMES, hasProbes: true }), ex("probes"));
  assert.equal(at("uvm_test_top.e.probe_mon", NAMES).exact, false);
});

test("bench names: from a live configuration and the inferred components — never a throw", () => {
  assert.deepEqual(
    R.benchNames(
      {
        dut: { name: "buf" },
        agents: [{ name: "cmd" }, { name: "rsp" }],
        analysis: { scoreboards: [{ name: "pkt_sb", source: "cmd" }, { source: "rsp" }], coverage: ["cmd"] },
        subenvs: [{ name: "u_a" }],
        probes: [{ name: "p0" }],
      },
      []
    ),
    { dut: "buf", agents: ["cmd", "rsp"], scoreboards: ["pkt_sb", "sbd"], subenvs: ["u_a"], implicitCoverage: null, soleAgent: null, hasProbes: true },
    "an unnamed declared scoreboard is the instance `sbd`"
  );
  // implicit mode: what quick-uvm infers IS the scoreboard and the collector
  const inferred = [
    { kind: "scoreboard", name: "sbd", source: "cmd" },
    { kind: "coverage", name: "cmd", source: "cmd" },
  ];
  const imp = R.benchNames({ dut: { name: "buf" }, agents: [{ name: "cmd" }] }, inferred);
  assert.deepEqual([imp.scoreboards, imp.implicitCoverage], [["sbd"], "cmd"]);
  // a sole agent with replicas / instances
  assert.equal(R.benchNames({ agents: [{ name: "cmd", replicas: 2 }] }).soleAgent, "cmd");
  assert.equal(R.benchNames({ agents: [{ name: "cmd", instances: [{ name: "lo" }] }] }).soleAgent, "cmd");
  assert.equal(R.benchNames({ agents: [{ name: "cmd", replicas: 2 }, { name: "x" }] }).soleAgent, null);
  assert.equal(R.benchNames({ agents: [{ name: "cmd" }] }).soleAgent, null);
  // review: the shapes a half-typed file has (this runs on every edit)
  for (const cfg of [
    null, "x", 5, {},
    { agents: "foo", analysis: "x", subenvs: 7, probes: {}, dut: [] },
    { agents: [null, "s", {}, { name: 3 }], analysis: { scoreboards: "foo" }, subenvs: [null] },
    { agents: [{ name: "a" }], analysis: { scoreboards: [null, "s", { name: "k" }] } },
  ]) {
    assert.doesNotThrow(() => R.benchNames(cfg, [{ kind: "scoreboard" }, { kind: "x" }]));
  }
  assert.deepEqual(R.benchNames({ agents: [null, { name: "a" }], analysis: { scoreboards: [null, { name: "k" }] } }).scoreboards, ["k"]);
});

// ----------------------------------------------------------------- coverage
test("coverage (real imc summary): the tree, the columns with a space in their name, n/a absent", () => {
  const rows = R.parseImcSummary(fx("errors", "cov", "summary.txt"));
  assert.deepEqual(rows.map((r) => r.path.join(".")), [
    "uvm_pkg",
    "uvm_pkg.uvm_test_top",
    "uvm_pkg.uvm_test_top.e",
    "uvm_pkg.uvm_test_top.e.cmd_cov_h",
    "tb_top",
    "tb_top.ck",
    "tb_top.cmd_if_inst",
    "tb_top.rsp_if_inst",
    "tb_top.dut_inst",
  ]);
  const cov = rows.find((r) => r.path.at(-1) === "cmd_cov_h");
  assert.deepEqual(cov.metrics, {
    "CoverGroup Average": { pct: 100, covered: null, total: null },
    "CoverGroup Covered": { pct: 100, covered: 16, total: 16 },
  });
  const dut = rows.find((r) => r.path.at(-1) === "dut_inst");
  assert.deepEqual(dut.metrics.Block, { pct: 100, covered: 7, total: 7 });
  assert.ok(dut.metrics.Expression && dut.metrics.Toggle);
  assert.equal("Statement" in dut.metrics, false, "n/a is not a figure");
  assert.deepEqual(rows[0].metrics, {});
  // the other real run: a collector that covered nothing
  const zero = R.parseImcSummary(fx("fatal", "cov", "summary.txt")).find((r) => r.path.at(-1) === "cmd_cov_h");
  assert.deepEqual(zero.metrics["CoverGroup Covered"], { pct: 0, covered: 0, total: 16 });
  assert.deepEqual(R.parseImcSummary(""), []);
  assert.deepEqual(R.parseImcSummary("imc: *E,NOLIC: no licence\n"), [], "not a table: nothing, not a throw");
});

// ----------------------------------------------------------------- snapshot
test("snapshot (real, errors): the scoreboard carries the errors, folded by kind; coverage on its boxes", () => {
  const runs = [run("errors", "yapp_buffer_test.1"), run("errors", "smoke_test.1")];
  const s = R.summarizeResults(runs, R.parseImcSummary(fx("errors", "cov", "summary.txt")), NAMES);
  assert.deepEqual(s.runs.map((r) => `${r.test}.${r.seed}:${r.status}`), ["yapp_buffer_test.1:FAIL", "smoke_test.1:FAIL"]);
  assert.deepEqual([s.passed, s.failed, s.missed], [0, 2, 0]);
  assert.deepEqual(Object.keys(s.elements), ["sb:pkt_sb"], "everything was raised by the comparator");
  const sb = s.elements["sb:pkt_sb"];
  assert.equal(sb.fatals, 0);
  assert.equal(sb.errors, runs[0].counts.error + runs[1].counts.error);
  assert.equal(sb.warnings, runs[0].counts.warning + runs[1].counts.warning);
  // the same kind in two runs is one line; the run named is the FIRST
  assert.deepEqual(sb.messages.map((m) => [m.severity, m.id, m.count]), [
    ["error", "SB_NOEXP", 62], ["error", "ERROR", 140], ["error", "FAILED", 2], ["warning", "SB_LEFTOVER", 2],
  ], "worst first, then in order of appearance");
  const mismatch = sb.messages.find((m) => m.id === "ERROR");
  assert.ok(mismatch.message.startsWith("Expected:"));
  assert.equal(mismatch.file, "../tb/yapp_buffer_comparator.svh");
  assert.equal(mismatch.run, "yapp_buffer_test.1");
  assert.equal(sb.messages.reduce((n, m) => n + m.count, 0), sb.errors + sb.warnings, "nothing is lost in the fold");
  assert.deepEqual(s.coverage["cov:cmd"], [{ label: "cg", pct: 100, covered: 16, total: 16 }]);
  assert.deepEqual(s.coverage.dut.map((f) => f.label), ["block", "expr", "toggle"]);
  assert.equal(R.worstOf(sb), "error");
});

test("snapshot (real, fatal): the fatal lands on the scoreboard whose predictor raised it", () => {
  const s = R.summarizeResults([run("fatal", "yapp_buffer_test.1")], [], NAMES);
  assert.deepEqual(s.elements["sb:pkt_sb"], {
    fatals: 1, errors: 0, warnings: 0,
    messages: [{
      severity: "fatal", id: "UNFILLED_PREDICTOR", count: 1,
      message: s.elements["sb:pkt_sb"].messages[0].message,
      file: "../tb/yapp_buffer_reference_model.svh", line: 43, run: "yapp_buffer_test.1",
    }],
  });
  assert.deepEqual(s.coverage, {});
});

test("worst: a fatal outranks an error outranks a warning; nothing is null", () => {
  assert.equal(R.worstOf({ fatals: 1, errors: 5, warnings: 9 }), "fatal");
  assert.equal(R.worstOf({ fatals: 0, errors: 5, warnings: 9 }), "error");
  assert.equal(R.worstOf({ fatals: 0, errors: 0, warnings: 9 }), "warning");
  assert.equal(R.worstOf({ fatals: 0, errors: 0, warnings: 0 }), null);
  assert.equal(R.worstOf(undefined), null);
  assert.equal(R.countLabel({ fatals: 1, errors: 2, warnings: 9 }), "✕ 3", "failures first");
  assert.equal(R.countLabel({ fatals: 0, errors: 0, warnings: 9 }), "! 9");
});

const rep = (path, file = null, sev = "error", id = "X", line = 1, count = 1) =>
  ({ severity: sev, file, line, time: 1, path, id, message: `${id} text`, count });
const oneRun = (reports, extra = {}) => [{
  test: "t", seed: "1", status: "FAIL", counts: { info: 0, warning: 0, error: 0, fatal: 0 },
  reports, scope: null, missed: 0, ...extra,
}];

test("snapshot: a unit counts on its agent AND under its own key; an unknown path goes to its file's owner, then the env", () => {
  const runs = oneRun([
    rep("uvm_test_top.e.cmd_agnt.mon"),
    rep("uvm_test_top.e.cmd_agnt.drv", null, "error", "X", 1, 3),
    rep("reporter", "../tb/rsp_monitor.svh"),
    rep("reporter", "../tb/unknown.svh"),
    // review: under the env, in an instance the path rules do not know — the
    // source file names the owner before the env gets it
    rep("uvm_test_top.e.cmd_0_agnt.mon", "../tb/rsp_monitor.svh"),
    rep("uvm_test_top.e.who_knows", "../tb/unknown.svh"),
  ]);
  const owner = (f) => (f.endsWith("rsp_monitor.svh") ? "agent:rsp" : null);
  const s = R.summarizeResults(runs, [], NAMES, owner);
  assert.equal(s.elements["agent:cmd"].errors, 4, "a kind's COUNT is added, not 1");
  assert.equal(s.elements["agent:cmd:u.monitor"].errors, 1);
  assert.equal(s.elements["agent:cmd:u.driver"].errors, 3);
  assert.equal(s.elements["agent:rsp"].errors, 2, "by the owner of the source file");
  assert.equal(s.elements.env.errors, 2, "nobody owns it: the env — never dropped");
  // an EXACT path is not second-guessed by the file
  const exact = R.summarizeResults(oneRun([rep("uvm_test_top.e.cmd_agnt.mon", "../tb/rsp_monitor.svh")]), [], NAMES, owner);
  assert.deepEqual(Object.keys(exact.elements).sort(), ["agent:cmd", "agent:cmd:u.monitor"]);
  // without the manifest, everything unknown goes to the env
  assert.equal(R.summarizeResults(runs, [], NAMES).elements.env.errors, 4);
  assert.equal(R.summarizeResults(oneRun([], { missed: 3 }), [], NAMES).missed, 3);
});

test("snapshot (review): the message cap keeps the WORST — a late fatal is not dropped behind earlier warnings", () => {
  const many = Array.from({ length: R.MAX_MESSAGES + 4 }, (_, i) => rep("uvm_test_top.e.pkt_sb", "f.svh", "warning", `W${i}`, i));
  const s = R.summarizeResults(
    oneRun([...many, rep("uvm_test_top.e.pkt_sb", "f.svh", "fatal", "DEAD", 99), rep("uvm_test_top.e.pkt_sb", "f.svh", "error", "BAD", 98)]),
    [], NAMES
  );
  const sb = s.elements["sb:pkt_sb"];
  assert.equal(sb.messages.length, R.MAX_MESSAGES, "capped");
  assert.deepEqual(sb.messages.slice(0, 2).map((m) => m.id), ["DEAD", "BAD"], "the fatal and the error are there, first");
  assert.equal(sb.warnings, R.MAX_MESSAGES + 4, "the counts are never capped");
  assert.deepEqual(sb.messages.slice(2, 4).map((m) => m.id), ["W0", "W1"], "the earliest of the least severe stay");
  // the same holds where a level merges several elements into one block
  const lv = R.levelResults(
    R.summarizeResults(oneRun([...many, rep("uvm_test_top.e.cmd_agnt", "f.svh", "fatal", "DEAD", 99)]), [], NAMES),
    "", ["dut", "env"]
  );
  assert.equal(lv.nodes.env.messages[0].id, "DEAD");
  assert.equal(lv.nodes.env.messages.length, R.MAX_MESSAGES);
});

test("snapshot: coverage only on what the configuration has; implicit mode's `cov`; the DUT's SUBTREE", () => {
  const rows = R.parseImcSummary(fx("errors", "cov", "summary.txt"));
  const none = R.summarizeResults([], rows, { agents: [], scoreboards: [], subenvs: [] });
  assert.equal("cov:cmd" in none.coverage, false, "an agent the config does not have gets no figure");
  assert.deepEqual(none.coverage.dut[0], { label: "block", pct: 100, covered: 7, total: 7 });
  assert.deepEqual(R.summarizeResults([], [], NAMES), { runs: [], passed: 0, failed: 0, elements: {}, coverage: {}, missed: 0 });
  // implicit mode: the collector's instance is `cov`
  const implicit = rows.map((r) => (r.path.at(-1) === "cmd_cov_h" ? { ...r, path: [...r.path.slice(0, -1), "cov"] } : r));
  const names = { agents: ["cmd"], scoreboards: ["sbd"], subenvs: [], implicitCoverage: "cmd" };
  assert.deepEqual(R.summarizeResults([], implicit, names).coverage["cov:cmd"], [{ label: "cg", pct: 100, covered: 16, total: 16 }]);
  assert.equal("cov:cmd" in R.summarizeResults([], implicit, NAMES).coverage, false);
  // review: imc's rows are per INSTANCE — a hierarchical DUT is its subtree
  const deep = [
    ...rows,
    { path: ["tb_top", "dut_inst", "u_core"], metrics: { Block: { pct: 10, covered: 1, total: 10 }, Toggle: { pct: 50, covered: null, total: null } } },
  ];
  const dut = R.summarizeResults([], deep, NAMES).coverage.dut;
  assert.deepEqual(dut.find((f) => f.label === "block"), { label: "block", pct: 47.06, covered: 8, total: 17 }, "7/7 + 1/10");
  assert.deepEqual(dut.find((f) => f.label === "toggle"), { label: "toggle", pct: 97.3, covered: 36, total: 37 },
    "a bare percentage cannot be summed: the DUT's own row, the best that can be said");
});

// ------------------------------------------------------ what a level shows
const SNAP = () =>
  R.summarizeResults(
    oneRun([
      rep("uvm_test_top.e.cmd_agnt.mon"),
      rep("uvm_test_top.e.cmd_agnt.drv", null, "warning"),
      rep("uvm_test_top.e.cmd_agnt", null, "error", "OWN"),
      rep("uvm_test_top.e.pkt_sb.cmp"),
      rep("uvm_test_top.e", null, "fatal", "ENV"),
      rep("uvm_test_top.e.rsp_cov_h"),
    ]),
    R.parseImcSummary(fx("errors", "cov", "summary.txt")),
    NAMES
  );

test("level: at the testbench level the env block carries everything inside it; coverage is not summed", () => {
  const { nodes, elsewhere } = R.levelResults(SNAP(), "", ["dut", "env"]);
  assert.deepEqual([nodes.env.fatals, nodes.env.errors, nodes.env.warnings], [1, 4, 1], "an error two levels down is still on screen");
  assert.deepEqual(nodes.env.coverage, [], "a figure belongs to one instance");
  assert.deepEqual(nodes.dut.coverage.map((f) => f.label), ["block", "expr", "toggle"]);
  assert.equal(nodes.dut.errors, 0);
  assert.equal(elsewhere, null, "everything has a block here");
  assert.equal(R.worstOfNode(nodes.env), "fatal");
  assert.equal(R.worstOfNode(nodes.dut), null);
  // the DUT is not inside the environment: a result keyed `dut` never bubbles there
  const s = SNAP();
  s.elements.dut = { fatals: 0, errors: 7, warnings: 0, messages: [] };
  assert.equal(R.levelResults(s, "", ["env"]).nodes.env.errors, 4);
  assert.equal(R.levelResults(s, "", ["env"]).elsewhere.errors, 7);
});

test("level: at the env level each block shows its own; what has no block is ELSEWHERE, never nowhere", () => {
  const { nodes, elsewhere } = R.levelResults(SNAP(), "env", ["agent:cmd", "agent:rsp", "sb:pkt_sb", "cov:cmd", "cov:rsp", "vsqr"]);
  assert.deepEqual([nodes["agent:cmd"].errors, nodes["agent:cmd"].warnings], [2, 1], "the agent's total, units included ONCE");
  assert.equal(nodes["sb:pkt_sb"].errors, 1);
  assert.equal(nodes["cov:rsp"].errors, 1);
  assert.deepEqual(nodes["cov:cmd"].coverage, [{ label: "cg", pct: 100, covered: 16, total: 16 }]);
  assert.equal(nodes["agent:rsp"], undefined, "nothing reported: no entry, no badge");
  assert.equal(Object.keys(nodes).some((k) => k.includes(":u.")), false);
  // review: the env's own fatal has no block on this level — it used to vanish
  assert.deepEqual([elsewhere.fatals, elsewhere.errors, elsewhere.warnings], [1, 0, 0]);
  assert.deepEqual(elsewhere.messages.map((m) => m.id), ["ENV"]);
});

test("level: at an agent's level its units; the agent's own and the rest of the bench are elsewhere", () => {
  const { nodes, elsewhere } = R.levelResults(SNAP(), "agent:cmd", ["u.sequencer", "u.driver", "u.monitor"]);
  assert.deepEqual(Object.keys(nodes).sort(), ["u.driver", "u.monitor"]);
  assert.equal(nodes["u.monitor"].errors, 1);
  assert.equal(nodes["u.driver"].warnings, 1);
  // elsewhere: the agent's OWN report (1 error) + the scoreboard's + the
  // collector's + the env's fatal — the units' two are not counted again
  assert.deepEqual([elsewhere.fatals, elsewhere.errors, elsewhere.warnings], [1, 3, 0]);
  const other = R.levelResults(SNAP(), "agent:rsp", ["u.sequencer", "u.driver", "u.monitor"]);
  assert.deepEqual(other.nodes, {}, "another agent's units are not this level's");
  assert.deepEqual([other.elsewhere.fatals, other.elsewhere.errors, other.elsewhere.warnings], [1, 4, 1]);
  // a cross-block scoreboard is drawn at the testbench level: its own block wins over the env
  const x = R.levelResults(SNAP(), "", ["env", "xsb:pkt_sb"]);
  assert.equal(x.nodes["xsb:pkt_sb"].errors, 1);
  assert.equal(x.nodes.env.errors, 3);
  assert.deepEqual(R.levelResults(null, "env", ["agent:cmd"]), { nodes: {}, elsewhere: null });
});

// -------------------------------------------------- the header and the report
test("chip: the VERDICTS of the runs, and that they are stale", () => {
  const s = (runs) => ({ runs, passed: runs.filter((r) => r.status === "PASS").length, failed: runs.filter((r) => r.status === "FAIL").length, elements: {}, coverage: {}, missed: 0 });
  const r = (status) => ({ test: "t", seed: "1", status });
  assert.deepEqual(R.resultsChip(s([r("PASS"), r("PASS")]), false), { text: "Runs: 2 passed", tone: "pass" });
  assert.deepEqual(R.resultsChip(s([r("PASS"), r("FAIL"), r("FAIL")]), false), { text: "Runs: 1/3 passed", tone: "fail" });
  assert.deepEqual(R.resultsChip(s([r("PASS"), r("UNKNOWN")]), true), { text: "Runs: 1 passed, 1 without a verdict (stale)", tone: "unknown" });
});

test("report (real): runs, elements with folded messages, coverage; nothing incomplete is implied", () => {
  const runs = [run("errors", "yapp_buffer_test.1"), run("errors", "smoke_test.1")];
  const snapshot = R.summarizeResults(runs, R.parseImcSummary(fx("errors", "cov", "summary.txt")), NAMES);
  const text = R.resultsReport({ snapshot, dir: "/w/tb/out", at: Date.UTC(2026, 10, 21, 9, 30), unparsed: 0 }, { name: "yapp_buffer.quickuvm.yaml", stale: false });
  assert.match(text, /^# Simulation results — yapp_buffer\.quickuvm\.yaml/);
  assert.match(text, /2 runs: 0 passed, 2 failed — 2026-11-21 09:30 UTC/);
  assert.match(text, /\| yapp_buffer_test \| 1 \| FAIL \|/);
  assert.match(text, /### `sb:pkt_sb` — 204 errors, 2 warnings/);
  assert.match(text, /- UVM_ERROR \[ERROR\] ×140 — Expected:.*\(yapp_buffer_comparator\.svh:135, yapp_buffer_test\.1\)/);
  assert.match(text, /- `cov:cmd`: cg 100% \(16\/16\)/);
  assert.doesNotMatch(text, /Stale|Partial|Old coverage|more of other/);
  const flagged = R.resultsReport(
    { snapshot: { ...snapshot, missed: 4 }, dir: "d", at: null, unparsed: 2 },
    { name: "x", stale: true, covStale: true }
  );
  assert.match(flagged, /\*\*Stale:\*\*/);
  assert.match(flagged, /\*\*Old coverage:\*\*/);
  assert.match(flagged, /\*\*Partial:\*\* 2 logs were not parsed/);
  assert.match(flagged, /\*\*Partial:\*\* the simulator counted 4 more/);
  const clean = R.resultsReport({ snapshot: R.summarizeResults([], [], NAMES), dir: "d", at: null, unparsed: 0 }, { name: "x", stale: false });
  assert.match(clean, /No warning, error or fatal was reported\./);
});

test("report (review): worst element first, a unit not listed twice, what the cap hid is said, a run without a verdict too", () => {
  const many = Array.from({ length: R.MAX_MESSAGES + 3 }, (_, i) => rep("uvm_test_top.e.rsp_agnt", "f.svh", "warning", `W${i}`, i));
  const snapshot = R.summarizeResults(
    [
      ...oneRun([
        rep("uvm_test_top.e.cmd_agnt.mon"),
        rep("uvm_test_top.e.pkt_sb", null, "fatal", "DEAD"),
        ...many,
      ]),
      { test: "u", seed: "2", status: "UNKNOWN", counts: { info: 0, warning: 0, error: 0, fatal: 0 }, reports: [], scope: null, missed: 0 },
    ],
    [], NAMES
  );
  const text = R.resultsReport({ snapshot, dir: "d", at: null, unparsed: 0 }, { name: "x", stale: false });
  const order = [...text.matchAll(/^### `([^`]+)`/gm)].map((m) => m[1]);
  assert.deepEqual(order, ["sb:pkt_sb", "agent:cmd", "agent:rsp"], "a fatal, then an error, then warnings — and no `agent:cmd:u.monitor`");
  assert.match(text, /… and 3 more of other, less severe kinds/);
  assert.match(text, /2 runs: 0 passed, 1 failed, 1 without a verdict \(still running, or stopped\)/);
  assert.match(text, /\| u \| 2 \| no verdict \|/);
  // a message line: the file's base name, whatever the separators
  assert.match(R.messageLine({ severity: "error", id: "A", message: "m", count: 2, file: "C:\\w\\tb\\x.svh", line: 4, run: "t.1" }), /^UVM_ERROR \[A\] ×2 — m \(x\.svh:4, t\.1\)$/);
  assert.match(R.messageLine({ severity: "warning", id: "A", message: "m", count: 1, file: null, line: null, run: "t.1" }), /^UVM_WARNING \[A\] — m \(t\.1\)$/);
});

